def test_do_not_clamp_height_of_absolute_node_to_height_of_its_overflow_hidden_parent():
    config = Config()
    root = Node(config)
    root.flex_direction = FlexDirection.ROW
    root.position_type = PositionType.ABSOLUTE
    root.overflow = Overflow.HIDDEN
    root.width = 50
    root.height = 50
    root_child0 = Node(config)
    root_child0.position_type = PositionType.ABSOLUTE
    root_child0.set_position(Edge.START, 0)
    root_child0.set_position(Edge.TOP, 0)
    root.insert_child(root_child0, 0)
    root_child0_child0 = Node(config)
    root_child0_child0.width = 100
    root_child0_child0.height = 100
    root_child0.insert_child(root_child0_child0, 0)
    root.calculate_layout(None, None, Direction.LTR)
    assert root.layout.left == pytest.approx(0, abs=1e-4)
    assert root.layout.top == pytest.approx(0, abs=1e-4)
    assert root.layout.width == pytest.approx(50, abs=1e-4)
    assert root.layout.height == pytest.approx(50, abs=1e-4)
    assert root_child0.layout.left == pytest.approx(0, abs=1e-4)
    assert root_child0.layout.top == pytest.approx(0, abs=1e-4)
    assert root_child0.layout.width == pytest.approx(100, abs=1e-4)
    assert root_child0.layout.height == pytest.approx(100, abs=1e-4)
    assert root_child0_child0.layout.left == pytest.approx(0, abs=1e-4)
    assert root_child0_child0.layout.top == pytest.approx(0, abs=1e-4)
    assert root_child0_child0.layout.width == pytest.approx(100, abs=1e-4)
    assert root_child0_child0.layout.height == pytest.approx(100, abs=1e-4)
    root.calculate_layout(None, None, Direction.RTL)
    assert root.layout.left == pytest.approx(0, abs=1e-4)
    assert root.layout.top == pytest.approx(0, abs=1e-4)
    assert root.layout.width == pytest.approx(50, abs=1e-4)
    assert root.layout.height == pytest.approx(50, abs=1e-4)
    assert root_child0.layout.left == pytest.approx(-50, abs=1e-4)
    assert root_child0.layout.top == pytest.approx(0, abs=1e-4)
    assert root_child0.layout.width == pytest.approx(100, abs=1e-4)
    assert root_child0.layout.height == pytest.approx(100, abs=1e-4)
    assert root_child0_child0.layout.left == pytest.approx(0, abs=1e-4)
    assert root_child0_child0.layout.top == pytest.approx(0, abs=1e-4)
    assert root_child0_child0.layout.width == pytest.approx(100, abs=1e-4)
