def test_absolute_layout_column_reverse_margin_border():
    config = Config()
    root = Node(config)
    root.flex_direction = FlexDirection.COLUMN_REVERSE
    root.position_type = PositionType.ABSOLUTE
    root.width = 200
    root.height = 200
    root_child0 = Node(config)
    root_child0.position_type = PositionType.ABSOLUTE
    root_child0.set_position(Edge.LEFT, 5)
    root_child0.set_position(Edge.RIGHT, 3)
    root_child0.set_margin(Edge.LEFT, 3)
    root_child0.set_margin(Edge.RIGHT, 4)
    root_child0.set_border(Edge.LEFT, 1)
    root_child0.set_border(Edge.RIGHT, 7)
    root_child0.width = 50
    root_child0.height = 50
    root.insert_child(root_child0, 0)
    root.calculate_layout(None, None, Direction.LTR)
    assert root.layout.left == pytest.approx(0, abs=1e-4)
    assert root.layout.top == pytest.approx(0, abs=1e-4)
    assert root.layout.width == pytest.approx(200, abs=1e-4)
    assert root.layout.height == pytest.approx(200, abs=1e-4)
    assert root_child0.layout.left == pytest.approx(8, abs=1e-4)
    assert root_child0.layout.top == pytest.approx(150, abs=1e-4)
